import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../dist/', import.meta.url);
const [words, game, app] = await Promise.all([
  readFile(new URL('words.mjs', root), 'utf8'),
  readFile(new URL('game.mjs', root), 'utf8'),
  readFile(new URL('app.js', root), 'utf8')
]);

const source = `// Generated by scripts/build-bundle.mjs. Edit the source modules instead.\n(() => {\n'use strict';\n${words.replace(/^export /gm, '')}\n${game.replace(/^export /gm, '')}\n${app.replace(/^import .*?;\s*/gm, '')}\n})();\n`;
await writeFile(new URL('app.bundle.js', root), source);
console.log(`Built dist/app.bundle.js (${source.length} bytes).`);
